import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Container,
  Paper,
  TextField,
  Button,
  Typography,
  Box,
  Alert,
  CircularProgress,
} from '@mui/material';
import { useAuth } from '../context/AuthContext';
import { validateLoginForm } from '../utils/validation';
import { useDemoMode } from '../hooks/useDemoMode';

const Login = () => {
  const [formData, setFormData] = useState({
    email: '',
    password: '',
  });
  const [errors, setErrors] = useState({});
  const navigate = useNavigate();
  const { login, isLoading, error, clearError } = useAuth();
  const { getDemoCredentials, isDemoMode } = useDemoMode();

  // Auto-fill demo credentials when demo mode is enabled
  useEffect(() => {
    if (isDemoMode) {
      const credentials = getDemoCredentials();
      setFormData(credentials);
      setErrors({});
    }
  }, [isDemoMode, getDemoCredentials]);

  // Listen for demo credentials event
  useEffect(() => {
    const handleDemoCredentials = (event) => {
      const credentials = event.detail;
      setFormData(credentials);
      setErrors({});
    };

    window.addEventListener('demoCredentials', handleDemoCredentials);
    return () => {
      window.removeEventListener('demoCredentials', handleDemoCredentials);
    };
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value,
    }));

    // Clear field error when user starts typing
    if (errors[name]) {
      setErrors(prev => ({
        ...prev,
        [name]: '',
      }));
    }

    // Clear general error when user starts typing
    if (error) {
      clearError();
    }
  };

  const validateForm = () => {
    const validationErrors = validateLoginForm(formData);
    setErrors(validationErrors || {});
    return !validationErrors;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    try {
      await login(formData.email, formData.password);
      navigate('/dashboard');
    } catch (err) {
      // Error is handled by the auth context
    }
  };

  const handleDemoLogin = () => {
    const credentials = getDemoCredentials();
    setFormData(credentials);
    setErrors({});
  };

  return (
    <Container component="main" maxWidth="sm">
      <Box
        sx={{
          marginTop: 8,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
        }}
      >
        <Paper elevation={3} sx={{ padding: 4, width: '100%' }}>
          <Box sx={{ textAlign: 'center', mb: 3 }}>
            <Typography component="h1" variant="h4" color="primary">
              Site Survey Tool
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
              ISP Site Survey Management System
            </Typography>

            {/* Demo Mode Indicator */}
            {isDemoMode && (
              <Box sx={{ mt: 2 }}>
                <Typography variant="caption" color="success.main" sx={{ fontWeight: 'bold' }}>
                  🎭 DEMO MODE ACTIVE - Using sample credentials
                </Typography>
              </Box>
            )}
          </Box>

          {error && (
            <Alert severity="error" sx={{ mb: 2 }}>
              {error}
            </Alert>
          )}

          <Box component="form" onSubmit={handleSubmit} sx={{ mt: 1 }}>
            <TextField
              margin="normal"
              required
              fullWidth
              id="email"
              label="Email Address"
              name="email"
              autoComplete="email"
              autoFocus
              value={formData.email}
              onChange={handleChange}
              error={!!errors.email}
              helperText={errors.email}
              disabled={isLoading}
            />
            <TextField
              margin="normal"
              required
              fullWidth
              name="password"
              label="Password"
              type="password"
              id="password"
              autoComplete="current-password"
              value={formData.password}
              onChange={handleChange}
              error={!!errors.password}
              helperText={errors.password}
              disabled={isLoading}
            />
            <Button
              type="submit"
              fullWidth
              variant="contained"
              sx={{ mt: 3, mb: 2 }}
              disabled={isLoading}
            >
              {isLoading ? (
                <CircularProgress size={24} color="inherit" />
              ) : (
                'Sign In'
              )}
            </Button>
          </Box>

          <Box sx={{ mt: 2, textAlign: 'center' }}>
            <Typography variant="body2" color="text.secondary" gutterBottom>
              Demo Credentials:
            </Typography>
            <Button
              variant="outlined"
              size="small"
              onClick={handleDemoLogin}
              sx={{ mb: 1 }}
            >
              Auto-fill Demo Login
            </Button>
            <Typography variant="caption" display="block">
              Email: {getDemoCredentials().email}
            </Typography>
            <Typography variant="caption" display="block">
              Password: {getDemoCredentials().password}
            </Typography>
          </Box>
        </Paper>
      </Box>
    </Container>
  );
};

export default Login;
